const item = $input.first().json;
const raw =
  typeof item.text === 'string'
    ? item.text
    : typeof item.output === 'string'
      ? item.output
      : '';

let stripped = String(raw)
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let data = null;
try {
  data = JSON.parse(stripped);
} catch (e) {
  const m = stripped.match(/\{[\s\S]*\}/);
  if (m) {
    try {
      data = JSON.parse(m[0]);
    } catch (e2) {}
  }
}

function norm(v) {
  if (typeof v === 'string' && v.includes(',')) {
    return v.split(',').map((s) => s.trim()).filter(Boolean).slice(0, 5);
  }
  if (Array.isArray(v)) return v.slice(0, 5);
  if (v == null || v === '') return [];
  return [String(v)];
}

if (!data || typeof data !== 'object') {
  return [{ json: { output: null, extract_error: true, raw_preview: String(raw).slice(0, 500) } }];
}

const output = {
  property_type: data.property_type ?? 'other',
  location: data.location ?? '',
  price_ils: typeof data.price_ils === 'number' ? data.price_ils : data.price_ils == null ? null : Number(data.price_ils) || null,
  num_rooms: typeof data.num_rooms === 'number' ? data.num_rooms : data.num_rooms == null ? null : parseInt(String(data.num_rooms), 10) || null,
  key_features: norm(data.key_features),
  certifications: data.certifications != null ? String(data.certifications) : '',
};

return [{ json: { output } }];

const item = $input.first().json;
const raw =
  typeof item.text === 'string'
    ? item.text
    : typeof item.output === 'string'
      ? item.output
      : '';

let stripped = String(raw)
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let data = null;
try {
  data = JSON.parse(stripped);
} catch (e) {
  const m = stripped.match(/\{[\s\S]*\}/);
  if (m) {
    try {
      data = JSON.parse(m[0]);
    } catch (e2) {}
  }
}

if (data && data.report && typeof data.report === 'object') {
  data = data.report;
}

const fallback = {
  property_type: 'unknown',
  routing_decision: 'residential',
  location: 'unknown',
  price_ils: null,
  num_rooms: null,
  key_features: [],
  image_scores: [],
  similar_listings: [],
  rag_insight: '',
  enrichment_notes: 'Could not parse final report JSON from the LLM chain output.',
  confidence: 0,
  parse_error: true,
};

if (!data || typeof data !== 'object') {
  return [{ json: { ...fallback, raw_preview: typeof raw === 'string' ? raw.slice(0, 800) : '' } }];
}

return [{ json: data }];
